import { writeFile } from 'node:fs/promises';
import { isDeepStrictEqual } from 'node:util';
import { createClient } from '@supabase/supabase-js';
import { stories } from '../content/stories/originals';
import { validateStory } from '../src/lib/stories/types';
for (const s of stories) validateStory(s);
if (
  new Set(stories.map((s) => s.slug + ':' + s.revision)).size !== stories.length
)
  throw Error('Duplicate story revision');
const quote = (s: string) => "'" + s.replaceAll("'", "''") + "'";
const seed =
  '-- Generated by scripts/import-stories.ts; edit content/stories/originals.ts instead.\nBEGIN;\n' +
  stories
    .map(
      (s) =>
        `INSERT INTO public.interactive_stories(slug,revision,title,subtitle,description,level,minutes,free_preview,published,document) VALUES(${quote(s.slug)},${s.revision},${quote(s.title)},${quote(s.subtitle)},${quote(s.description)},${quote(s.level)},${s.minutes},${s.free_preview},${s.published},${quote(JSON.stringify(s.document))}::jsonb) ON CONFLICT(slug,revision) DO NOTHING;`,
    )
    .join('\n') +
  '\nCOMMIT;\n';
if (process.argv.includes('--write-seed'))
  await writeFile('supabase/stories-seed.sql', seed);
if (process.argv.includes('--apply')) {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key =
    process.env.SUPABASE_SECRET_KEY ?? process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) throw Error('Supabase server configuration required');
  const db = createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const result = await db
    .from('interactive_stories')
    .upsert(stories, { onConflict: 'slug,revision', ignoreDuplicates: true });
  if (result.error)
    throw Error(
      'Story import failed; check schema, revision and published-slug uniqueness',
    );
  const { data, error } = await db
    .from('interactive_stories')
    .select('*')
    .in(
      'slug',
      stories.map((s) => s.slug),
    );
  if (
    error ||
    !data ||
    stories.some(
      (s) =>
        !Object.entries(s).every(([key, value]) =>
          isDeepStrictEqual(
            data.find(
              (row) => row.slug === s.slug && row.revision === s.revision,
            )?.[key],
            value,
          ),
        ),
    )
  )
    throw Error(
      'Imported content differs. Publish a new immutable revision instead of editing a used story.',
    );
  console.log('Supabase stories imported and verified.');
}
console.log(
  `Validated ${stories.length} original stories, ${stories.reduce((n, s) => n + Object.keys(s.document.nodes).length, 0)} nodes.`,
);
